import math

import torch

from gptqmodel.utils.logger import setup_logger


# Adapted from https://github.com/Cornell-RelaxML/quip-sharp/blob/main/lib/utils/matmul_had.py

log = setup_logger()
_FAST_HADAMARD_MODULE = None
_FAST_HADAMARD_IMPORT_FAILED = False


def get_hadK(n, transpose=False):
    hadK, K = None, None
    if n % 172 == 0:  # llama-2-7b up
        assert is_pow2(n // 172)
        K = 172
        hadK = get_had172().T if transpose else get_had172()
    elif n % 156 == 0:  # llama-1-30b 3x hidden
        assert is_pow2(n // 156)
        K = 156
        hadK = get_had156().T if transpose else get_had156()
    elif n % 140 == 0:  # llama-1-30b intermediate
        assert is_pow2(n // 140)
        K = 140
        hadK = get_had140().T if transpose else get_had140()
    elif n % 108 == 0:  # llama-1-13b intermediate
        assert is_pow2(n // 108)
        K = 108
        hadK = get_had108().T if transpose else get_had108()
    elif n % 60 == 0:  # llama-1-13b 3x hidden
        assert is_pow2(n // 60)
        K = 60
        hadK = get_had60().T if transpose else get_had60()
    elif n % 52 == 0:  # llama-1-13b 1x hidden
        assert is_pow2(n // 52)
        K = 52
        hadK = get_had52().T if transpose else get_had52()
    elif n % 36 == 0:
        assert is_pow2(n // 36)
        K = 36
        hadK = get_had36().T if transpose else get_had36()
    elif n % 28 == 0:  # llama-3 up
        assert is_pow2(n // 28)
        K = 28
        hadK = get_had28().T if transpose else get_had28()
    elif n % 40 == 0:
        assert is_pow2(n // 40)
        K = 40
        hadK = get_had40().T if transpose else get_had40()
    elif n % 20 == 0:
        assert is_pow2(n // 20)
        K = 20
        hadK = get_had20().T if transpose else get_had20()
    elif n % 12 == 0:
        assert is_pow2(n // 12)
        K = 12
        hadK = get_had12().T if transpose else get_had12()
    else:
        assert is_pow2(n)
        K = 1

    return hadK, K


def matmul_hadU(X, transpose=False):
    n = X.shape[-1]
    hadK, K = get_hadK(n, transpose)
    input = X.clone().view(-1, n, 1)
    output = input.clone()
    while input.shape[1] > K:
        input = input.view(input.shape[0], input.shape[1] // 2, 2, input.shape[2])
        output = output.view(input.shape)
        output[:, :, 0, :] = input[:, :, 0, :] + input[:, :, 1, :]
        output[:, :, 1, :] = input[:, :, 0, :] - input[:, :, 1, :]
        output = output.view(input.shape[0], input.shape[1], -1)
        (input, output) = (output, input)
    del output

    if K > 1:
        # Do not explicitly repeat - OOM
        # input = torch.bmm(
        #     hadK.repeat(len(input), 1, 1).to(input.device).to(input.dtype), input)
        # Use bcast instead
        input = hadK.view(1, K, K).to(input) @ input

    return input.view(X.shape) / torch.tensor(n).sqrt()


def matmul_hadUt(X):
    return matmul_hadU(X, transpose=True)


def random_hadamard_matrix(size, device):
    # See https://cornell-relaxml.github.io/quip-sharp/ , Section "Randomized Hadamard Transformation"
    Q = torch.randint(low=0, high=2, size=(size,)).to(torch.float64)
    Q = Q * 2 - 1
    Q = torch.diag(Q)
    return matmul_hadU(Q).to(device)

def random_block_hadamard_matrix(size, device, block_size: int = 64):
    """
    Generate a block-diagonal random Hadamard matrix.

    - The whole matrix is size x size.
    - It is composed of blocks on the diagonal, each block being a randomized Hadamard matrix.
    - block_size must divide size and be a power of 2 to be compatible with Hadamard.

    If block_size is not valid for the given size, this function falls back to full random_hadamard_matrix(size, device).
    """
    if block_size <= 0:
        return random_hadamard_matrix(size, device)

    if size % block_size != 0:
        # Fallback to global hadamard if cannot evenly split
        return random_hadamard_matrix(size, device)

    if not is_pow2(block_size):
        # Fallback to global hadamard if block_size is not a power of 2
        return random_hadamard_matrix(size, device)

    num_blocks = size // block_size
    # Build block-diagonal matrix; reuse the same Hadamard structure in each block but with independent random signs
    blocks = []
    for _ in range(num_blocks):
        blocks.append(random_hadamard_matrix(block_size, device))
    return torch.block_diag(*blocks)


def import_fast_hadamard_transform(required=True):
    global _FAST_HADAMARD_MODULE, _FAST_HADAMARD_IMPORT_FAILED

    if _FAST_HADAMARD_MODULE is not None:
        return _FAST_HADAMARD_MODULE
    if _FAST_HADAMARD_IMPORT_FAILED and not required:
        return None

    try:
        import fast_hadamard_transform

        _FAST_HADAMARD_MODULE = fast_hadamard_transform
        return _FAST_HADAMARD_MODULE
    except ImportError as e:
        _FAST_HADAMARD_IMPORT_FAILED = True
        install_hint = (
            "Package: Please install missing `fast_hadamard_transform` module via: "
            "`pip install -U git+https://github.com/Dao-AILab/fast-hadamard-transform.git --no-build-isolation -v`"
        )
        if required:
            log.error(install_hint)
            raise e
        log.warning(f"{install_hint}. Falling back to torch Hadamard implementation.")
        return None


def _chunked_hadamard_transform(input_tensor, had_dim, fast_hadamard_transform=None):
    reshaped = input_tensor.reshape(-1, input_tensor.shape[-1] // had_dim, had_dim)
    if fast_hadamard_transform is not None:
        return fast_hadamard_transform.hadamard_transform(
            reshaped,
            scale=1 / math.sqrt(had_dim),
        ).reshape(input_tensor.shape)
    # matmul_hadU uses .view() internally, so ensure contiguous layout for fallback path.
    return matmul_hadU(reshaped.contiguous()).reshape(input_tensor.shape)


def matmul_hadU_cuda(X, hadK, K):
    fast_hadamard_transform = import_fast_hadamard_transform(required=False)
    if fast_hadamard_transform is None:
        return matmul_hadU(X)

    n = X.shape[-1]
    if K == 1:
        return fast_hadamard_transform.hadamard_transform(X.contiguous(), 1.0 / torch.tensor(n).sqrt())  # noqa: F821
    # if transpose:
    #     hadK = hadK.T.contiguous()
    input = X.view(-1, K, n // K)
    input = fast_hadamard_transform.hadamard_transform(input.contiguous(), 1.0 / torch.tensor(n).sqrt())  # noqa: F821
    input = hadK.to(input.device).to(input.dtype) @ input
    return input.reshape(X.shape)


# def matmul_hadUt_cuda(X, hadK, K):
#     return matmul_hadU_cuda(X, hadK, K, transpose=True)


def apply_exact_had_to_linear(module, had_dim=-1, output=False):
    fast_hadamard_transform = import_fast_hadamard_transform(required=False)

    assert isinstance(module, torch.nn.Linear)
    in_features, out_features = module.in_features, module.out_features

    if had_dim != -1:
        assert is_pow2(had_dim), "Hadamard dimension must be a power of 2!"

    # weight
    W_ = module.weight.data
    dtype = W_.dtype
    dev = W_.device
    init_shape = W_.shape
    W_ = W_.float().cuda()

    # bias
    # bias needs to apply hadamard when output=True
    if module.bias is not None:
        b_ = module.bias.data
        b_dtype = b_.dtype
        b_init_shape = b_.shape
        b_ = b_.unsqueeze(0) if len(b_init_shape) == 1 else b_
        b_ = b_.float().cuda()

    if had_dim == -1:
        if output:
            had_K, K = get_hadK(out_features)
            W_ = matmul_hadU_cuda(W_.t(), had_K, K).t()
            if module.bias is not None:
                b_ = matmul_hadU_cuda(b_, had_K, K).reshape(b_init_shape)
        if not output:
            had_K, K = get_hadK(in_features)
            W_ = matmul_hadU_cuda(W_, had_K, K)
    else:
        # Apply Hadamard to the last had_dim chunks of the weights
        if output:
            W_ = W_.t()
            transposed_shape = W_.shape
            W_ = (
                _chunked_hadamard_transform(
                    W_,
                    had_dim,
                    fast_hadamard_transform=fast_hadamard_transform,
                )
                .reshape(transposed_shape)
                .t()
                .contiguous()
            )
            if module.bias is not None:
                b_ = (
                    _chunked_hadamard_transform(
                        b_,
                        had_dim,
                        fast_hadamard_transform=fast_hadamard_transform,
                    )
                    .reshape(b_init_shape)
                    .contiguous()
                )

        else:
            W_ = _chunked_hadamard_transform(
                W_,
                had_dim,
                fast_hadamard_transform=fast_hadamard_transform,
            ).reshape(init_shape)
    module.weight.data = W_.to(device=dev, dtype=dtype)
    if module.bias is not None:
        module.bias.data = b_.to(device=dev, dtype=b_dtype)


def is_pow2(n):
    return (n & (n - 1) == 0) and (n > 0)


